CREATE TABLE campus_jobs (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 owner_id BIGINT NOT NULL REFERENCES users(id), helper_id BIGINT REFERENCES users(id),
 title VARCHAR(120) NOT NULL, description VARCHAR(2000) NOT NULL,
 category VARCHAR(40) NOT NULL, reward DECIMAL(10,2) NOT NULL CHECK(reward BETWEEN 0 AND 10000),
 pickup VARCHAR(120) NOT NULL, destination VARCHAR(120) NOT NULL, deadline VARCHAR(40) NOT NULL,
 status VARCHAR(20) NOT NULL DEFAULT 'OPEN' CHECK(status IN ('OPEN','ACCEPTED','IN_PROGRESS','DELIVERED','COMPLETED','CANCELLED')),
 payment_status VARCHAR(20) NOT NULL DEFAULT 'UNPAID' CHECK(payment_status IN ('UNPAID','COLLECTED')),
 payment_method VARCHAR(20), collected_at VARCHAR(40), hidden BOOLEAN NOT NULL DEFAULT FALSE,
 created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL
);
CREATE INDEX ix_jobs_status ON campus_jobs(status,created_at);
CREATE INDEX ix_jobs_owner ON campus_jobs(owner_id);
CREATE INDEX ix_jobs_helper ON campus_jobs(helper_id);
CREATE TABLE job_messages(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, job_id BIGINT NOT NULL REFERENCES campus_jobs(id), sender_id BIGINT NOT NULL REFERENCES users(id), body VARCHAR(1000) NOT NULL, created_at VARCHAR(40) NOT NULL);
CREATE INDEX ix_messages_job ON job_messages(job_id,id);
CREATE TABLE notifications(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id), job_id BIGINT REFERENCES campus_jobs(id), message VARCHAR(300) NOT NULL, is_read BOOLEAN NOT NULL DEFAULT FALSE, created_at VARCHAR(40) NOT NULL);
CREATE INDEX ix_notifications_user ON notifications(user_id,id);
CREATE TABLE job_reviews(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, job_id BIGINT NOT NULL REFERENCES campus_jobs(id), reviewer_id BIGINT NOT NULL REFERENCES users(id), recipient_id BIGINT NOT NULL REFERENCES users(id), rating INT NOT NULL CHECK(rating BETWEEN 1 AND 5), comment VARCHAR(500) NOT NULL, created_at VARCHAR(40) NOT NULL, UNIQUE(job_id,reviewer_id));
CREATE TABLE job_reports(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, job_id BIGINT NOT NULL REFERENCES campus_jobs(id), reporter_id BIGINT NOT NULL REFERENCES users(id), reason VARCHAR(500) NOT NULL, resolved BOOLEAN NOT NULL DEFAULT FALSE, created_at VARCHAR(40) NOT NULL);
CREATE TABLE email_otps(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, email VARCHAR(254) NOT NULL, purpose VARCHAR(20) NOT NULL, code_hash VARCHAR(255) NOT NULL, expires_at VARCHAR(40) NOT NULL, sent_at VARCHAR(40) NOT NULL, attempts INT NOT NULL DEFAULT 0, used BOOLEAN NOT NULL DEFAULT FALSE, UNIQUE(email,purpose));
